class RandomizedSet {
public:
    RandomizedSet();

    // Inserts val if it is not already present. Returns true if val
    // was newly added, false if it was already in the set.
    bool insert(int val);

    // Removes val if it is present. Returns true if val was actually
    // removed, false if it was not found.
    bool remove(int val);

    // Returns a uniformly random element currently stored in the set.
    // The set is assumed to be non empty when this is called.
    int getRandom();
};

bool RandomizedSet::insert(int val) {
    if (idx.count(val)) return false;   // already present, no change

    vals.push_back(val);                // O(1) amortized append
    idx[val] = vals.size() - 1;         // remember where it landed
    return true;
}

bool RandomizedSet::remove(int val) {
    if (!idx.count(val)) return false;

    int removeIndex = idx[val];
    int lastIndex   = vals.size() - 1;

    swap(vals[removeIndex], vals[lastIndex]);   // move val to the back
    idx[vals[removeIndex]] = removeIndex;       // fix the map for the value that moved in

    vals.pop_back();       // O(1), removes val (now at the back)
    idx.erase(val);
    return true;
}

int RandomizedSet::getRandom() {
    int randomIndex = rand() % vals.size();
    return vals[randomIndex];
}

class RandomizedSet {
private:
    vector<int> vals;               // the actual stored values
    unordered_map<int, int> idx;    // value -> its current index inside vals

public:
    RandomizedSet() {
        srand(static_cast<unsigned>(time(nullptr)));
    }

    bool insert(int val) {
        if (idx.count(val)) return false;
        vals.push_back(val);
        idx[val] = vals.size() - 1;
        return true;
    }

    bool remove(int val) {
        auto it = idx.find(val);
        if (it == idx.end()) return false;

        int removeIndex = it->second;
        int lastIndex   = vals.size() - 1;

        // Swapping an element with itself, the case where val is
        // already the last element, is well defined and harmless,
        // so no special branch is needed here.
        swap(vals[removeIndex], vals[lastIndex]);
        idx[vals[removeIndex]] = removeIndex;

        vals.pop_back();
        idx.erase(val);
        return true;
    }

    int getRandom() {
        int randomIndex = rand() % vals.size();
        return vals[randomIndex];
    }
};
